head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > calendarClass]<br/>inputType='calendar' 인 Column 에서 팝업 달력의 요일에 적용될 백그라운드 이미지를 설정합니다.",
    "validation" : [
        "class1 설정 시, 팝업 달력의 요일이 세자리 영단어 대문자('SUN','MON')로 표시됩니다.",
        "미설정 시, 팝업 달력의 요일이 세자리 영단어 대문자('SUN','MON')로 표시됩니다.",
        "class2 설정 시, 팝업 달력의 요일이 한자리 한글('일','월')로 표시됩니다.",
        "class3 설정 시, 팝업 달력의 요일이 두자리 영단어('Su','Mo')가 굵게 표시됩니다.",
        "class4 설정 시, 팝업 달력의 요일이 두자리 영단어('Su','Mo')로 표시됩니다.",
        "class5 설정 시, 팝업 달력의 요일이 배경색이 있는 한자리 한글('일','월')로 표시됩니다.",
        "calendarClass 속성값에 관계없이 팝업 달력의 토요일은 파란색, 일요일은 빨간색으로 표시됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_calendarClass.setValue("class2");

    // 달력 아이콘 클릭으로 팝업 달력이 열리면 결과 출력 (페이지 로딩 시 1회만 등록)
    document.addEventListener("click", scwin.onDocumentClick, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - calendarClass 는 Body Column(cdate) 에만 설정
//  - Body Column 은 inputType="calendar" + dataType="date" + viewType="icon" (ioFormat yyyyMMdd / displayFormat yyyy-MM-dd)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let cCalendarClass = con_calendarClass.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] date 셀 클릭 -> 입력창 오른쪽 달력 아이콘 클릭 -> 팝업 달력 확인\n[확인] 팝업이 열리면 결과창에 적용 class / 요일 헤더 이미지 / 주말 날짜 색상이 출력됩니다."', '', 'label1');

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cdate" name="cdate" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([{ "cdate" : "20261001" }], false);

    // calendarClass 속성 문자열 (미설정이면 속성 자체를 넣지 않는다)
    let attrClass = (cCalendarClass === '') ? '' : ' calendarClass="' + cCalendarClass + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="date"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" id="cdate" inputType="calendar" dataType="date" viewType="icon"'
        + ' ioFormat="yyyyMMdd" displayFormat="yyyy-MM-dd"' + attrClass + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 화면에 열려 있는 target1 의 팝업 달력 render 반환 (없으면 null)
scwin.getOpenedCalendar = function () {
    if (typeof target1 === 'undefined' || !target1) {
        return null;
    }
    let cals = document.querySelectorAll("div.w2calendar[id*='G_" + target1.id + "__']");
    for (let i = 0; i < cals.length; i++) {
        if (cals[i].offsetWidth > 0 && cals[i].offsetHeight > 0) {
            return cals[i];
        }
    }
    return null;
}



// 달력 아이콘 클릭 시 팝업 달력이 열리면 결과 출력
scwin.onDocumentClick = function (e) {
    let elem = e.target;
    if (!elem || typeof target1 === 'undefined' || !target1) {
        return;
    }
    let btn = elem.closest ? elem.closest("button.w2inputCalendar_button") : null;
    if (!btn || btn.id.indexOf("G_" + target1.id + "__") < 0) {
        return;
    }
    setTimeout(scwin.printCalendarInfo, 300);
}



// 팝업 달력 정보 출력
scwin.printCalendarInfo = function () {
    let cal = scwin.getOpenedCalendar();
    if (!cal) {
        return;
    }
    let bottom = wf_body_bottom.getObj("scwin");
    let cCalendarClass = con_calendarClass.getValue();

    // validation 1 ~ 6 : 설정 조건과 팝업 달력에 적용된 class
    bottom.setReturnValue("calendarClass : " + (cCalendarClass === '' ? "(미설정)" : cCalendarClass)
        + " -> 팝업 달력 class : " + cal.className.split(" ").filter(function (c) { return c.indexOf("w2calendar_") === 0; }).join(" "));

    // validation 1 ~ 6 : 요일 헤더 (텍스트 / 백그라운드 이미지 파일명)
    let days = cal.querySelectorAll(".w2calendar_col_day .w2calendar_day");
    let dayInfo = [];
    for (let i = 0; i < days.length; i++) {
        let bg = getComputedStyle(days[i]).backgroundImage;
        let m = bg.match(/url\(["']?([^"')]*)["']?\)/);
        dayInfo.push(m ? m[1].split("/").pop() : "없음");
    }
    bottom.setReturnValue("요일 헤더 텍스트 : '" + (days.length > 0 ? days[0].textContent : "") + "' / 백그라운드 이미지 : " + dayInfo.join(", "));

    // validation 7 : 주말 날짜 색상 (두번째 주의 일요일 / 토요일 날짜)
    let sun = cal.querySelector("td[id$='_cell_1_0']");
    let sat = cal.querySelector("td[id$='_cell_1_6']");
    let sunElem = sun ? (sun.firstElementChild || sun) : null;
    let satElem = sat ? (sat.firstElementChild || sat) : null;
    bottom.setReturnValue("일요일 " + (sunElem ? sunElem.textContent + "일 color : " + getComputedStyle(sunElem).color : "")
        + " / 토요일 " + (satElem ? satElem.textContent + "일 color : " + getComputedStyle(satElem).color : ""));
}
